-- Rex configuration. Managed by chezmoi (home/dot_config/rex/init.lua).
-- Docs: https://www.superlogical.com/rex/docs/customize/config

-- One rex.host per workspace tunnel, so `rex -S <workspace>` works.
-- workspaces_rex.lua is generated by ~/.local/bin/workspaces-rex, which runs
-- `rex config reload` when it changes. Absent on machines without workspaces.
pcall(require, "workspaces_rex")

-- Rex Annotate: review agent replies and diffs in plannotator-tui. The module
-- is rendered by chezmoi (.chezmoitemplates/rex-annotate) once mise installs
-- plannotator-tui; until then this is a no-op.
local annotate_ok, annotate = pcall(require, "plannotator.annotate")
if annotate_ok then annotate.setup {} end

local function is_fg(p, name)
  local fg = p and p.foreground
  if not fg then return false end
  local a, n = fg.argv0 or "", fg.name or ""
  return a == name or a:match("/" .. name .. "$") ~= nil or n == name
end

-- Fullscreen pi and Claude Code run in the alternate screen where Rex's Find bar
-- has no scrollback; forward to their built-in transcript search instead.
rex.action {
  name = "smart_find",
  title = "Find (Agent-Aware)",
  description = "Open built-in transcript search in fullscreen pi/Claude panes, or Rex Find elsewhere.",
  run = function()
    local ok_p, p = pcall(rex.block.call, "com.superlogical.terminal", "process")
    local ok_m, m = pcall(rex.block.call, "com.superlogical.terminal", "modes")
    if ok_p and ok_m and m and m.screen == "alternate" then
      if is_fg(p, "pi") then
        -- CSI-u ctrl+shift+f (pi's tui.altScreen.search)
        rex.block.call("com.superlogical.terminal", "write", { data = "\27[102;6u" })
        return
      end
      if is_fg(p, "claude") then
        local ok_f, f = pcall(rex.block.call, "com.superlogical.terminal", "format")
        local content = (ok_f and f and type(f.content) == "string") and f.content or ""
        if content:find("Search transcript", 1, true) then return end
        if not content:find("Showing detailed transcript", 1, true) then
          rex.block.call("com.superlogical.terminal", "write", { data = "\15" }) -- ctrl+o
          rex.exec({ "sleep", "0.05" }) -- rex.sleep is script-only, missing in init.lua actions
        end
        rex.block.call("com.superlogical.terminal", "write", { data = "/" })
        return
      end
    end
    rex.client.queue("client.find.open")
  end,
}

local function term(method, args)
  return pcall(rex.block.call, "com.superlogical.terminal", method, args)
end

local function write(data)
  rex.block.call("com.superlogical.terminal", "write", { data = data })
end

-- Step through pi/Claude transcript search matches, or Rex Find matches elsewhere.
local function find_step(forward)
  local ok_p, p = term("process")
  local ok_m, m = term("modes")
  if ok_p and ok_m and m and m.screen == "alternate" and (is_fg(p, "pi") or is_fg(p, "claude")) then
    local ok_f, f = term("format")
    local content = (ok_f and f and type(f.content) == "string") and f.content or ""
    if is_fg(p, "pi") then
      -- shortcut: the box hides its buttons in very narrow panes, so cmd+g falls through to Rex Find there.
      if content:find("↓ Enter", 1, true) or content:find("Find in transcript", 1, true) then
        write(forward and "\7" or "\27[103;6u") -- ctrl+g / CSI-u ctrl+shift+g
        return
      end
    else
      local footer = content:gsub("%s+$", ""):match("([^\n]*)$") or ""
      if footer:find("n/N to navigate", 1, true) then
        write(forward and "n" or "N")
        return
      end
      if footer:match("^%s*/") then
        write("\r") -- commit the query; n/N only step once the input closes
        rex.exec({ "sleep", "0.05" })
        write(forward and "n" or "N")
        return
      end
    end
  end
  rex.client.queue(forward and "client.find.next" or "client.find.previous")
end

rex.action {
  name = "smart_find_next",
  title = "Find Next (Agent-Aware)",
  description = "Next transcript search match in fullscreen pi/Claude panes, or Rex Find Next elsewhere.",
  run = function() find_step(true) end,
}

rex.action {
  name = "smart_find_previous",
  title = "Find Previous (Agent-Aware)",
  description = "Previous transcript search match in fullscreen pi/Claude panes, or Rex Find Previous elsewhere.",
  run = function() find_step(false) end,
}

-- Mirror any init.lua bindings for the Rex Find actions, falling back to Rex's defaults.
local function mirror(action, default, smart)
  local bindings = rex.bindings { action = action }
  if #bindings == 0 then return rex.bind(default, smart) end
  for _, b in ipairs(bindings) do
    rex.bind(b.mode and (b.mode .. "/" .. b.key) or b.key, smart)
  end
end

mirror("client.find.open", "cmd+f", "smart_find")
mirror("client.find.next", "cmd+g", "smart_find_next")
mirror("client.find.previous", "cmd+shift+g", "smart_find_previous")
